    [InlineData(LoyaltyTier.Green, 10_000, 9_400)]
    [InlineData(LoyaltyTier.Green, 19_999, 18_400)]  // 8%, discount 1599.92 rounded down
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 200.00 belongs to the top band, 8%
    [InlineData(LoyaltyTier.Gold, 4_999, 4_650)]     // 7%, discount 349.93 rounded down
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10%
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)]  // 9%, discount 449.91 rounded down
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]  // 10%
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // 12 capped at 10
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        Assert.Equal(expectedPayableCents, new CalculatePayableTotal().For(subtotalCents, loyaltyTier));
    }
}
